use clap::{Arg, ArgAction, Command};
use indexmap::IndexMap;
use regex::Regex;
use std::cmp::Ordering;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

fn main() {
    let matches = Command::new("executable")
        .version("1.6.4")
        .about("Batch rename utility for developers")
        .after_help("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.")
        .arg(
            Arg::new("dir")
                .short('d')
                .long("dir")
                .value_name("PATH")
                .help("Sets the working directory"),
        )
        .arg(
            Arg::new("depth")
                .long("depth")
                .value_name("DEPTH")
                .value_parser(clap::value_parser!(usize))
                .help("Optional value to overwrite inferred subdirectory depth value in 'regex' mode"),
        )
        .arg(
            Arg::new("no-extension")
                .short('E')
                .long("no-extension")
                .action(ArgAction::SetTrue)
                .help("Does not preserve the extension of input files in 'sort' and 'regex' options"),
        )
        .arg(
            Arg::new("generate")
                .short('g')
                .long("generate")
                .value_name("PATH")
                .help("Stores a JSON map file in '<PATH>' after renaming files"),
        )
        .arg(
            Arg::new("mkdir")
                .short('k')
                .long("mkdir")
                .action(ArgAction::SetTrue)
                .help("Recursively creates all parent directories of '<OUTPUT>' if they are missing"),
        )
        .arg(
            Arg::new("map")
                .short('m')
                .long("map")
                .alias("from-file")
                .value_name("PATH")
                .help("Sets the path of map file to be used for renaming files"),
        )
        .arg(
            Arg::new("max-depth")
                .long("max-depth")
                .value_name("DEPTH")
                .value_parser(clap::value_parser!(usize))
                .help("Optional value to set the maximum of subdirectory depth value in 'regex' mode"),
        )
        .arg(
            Arg::new("quiet")
                .short('q')
                .long("quiet")
                .action(ArgAction::SetTrue)
                .help("Does not print the map table to stdout"),
        )
        .arg(
            Arg::new("regex")
                .short('r')
                .long("regex")
                .value_name("PATTERN")
                .help("Regex pattern to match by filenames"),
        )
        .arg(
            Arg::new("sort")
                .short('s')
                .long("sort")
                .value_name("ORDER")
                .value_parser(["asc", "desc"])
                .help("Sets the order of natural sorting (by name) to rename files using enumerator"),
        )
        .arg(
            Arg::new("test")
                .short('t')
                .long("test")
                .alias("dry-run")
                .action(ArgAction::SetTrue)
                .help("Runs in test mode without renaming actual files"),
        )
        .arg(
            Arg::new("overwrite")
                .short('w')
                .long("overwrite")
                .action(ArgAction::SetTrue)
                .help("Overwrites output files, otherwise, a '_' is prepended to filename"),
        )
        .arg(
            Arg::new("args")
                .value_name("[SOURCE] OUTPUT")
                .num_args(0..)
                .help("OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option"),
        )
        .get_matches();

    if let Some(dir) = matches.get_one::<String>("dir") {
        if let Err(e) = std::env::set_current_dir(dir) {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }

    let no_extension = matches.get_flag("no-extension");
    let quiet = matches.get_flag("quiet");
    let test_mode = matches.get_flag("test");
    let overwrite = matches.get_flag("overwrite");
    let make_dir = matches.get_flag("mkdir");
    let generate_path = matches.get_one::<String>("generate");
    let depth_opt = matches.get_one::<usize>("depth").copied();
    let max_depth_opt = matches.get_one::<usize>("max-depth").copied();

    let pos_args: Vec<String> = matches
        .get_many::<String>("args")
        .unwrap_or_default()
        .cloned()
        .collect();

    let regex_flag = matches.get_one::<String>("regex");
    let sort_flag = matches.get_one::<String>("sort");
    let map_flag = matches.get_one::<String>("map");

    let mode_flags_set = regex_flag.is_some() || sort_flag.is_some() || map_flag.is_some();

    if mode_flags_set && pos_args.len() > 1 {
        eprintln!("error: optional SOURCE must be used without setting regex, map or sort flags");
        std::process::exit(1);
    }

    enum RunMode<'a> {
        Regex(&'a str, String),
        Sort(&'a str, String),
        Map(&'a str),
    }

    let run_mode = if let Some(r_pattern) = regex_flag {
        let output_pattern = match pos_args.last() {
            Some(o) => o.clone(),
            None => {
                eprintln!("error: [output-format] output formatter must be set");
                std::process::exit(1);
            }
        };
        RunMode::Regex(r_pattern.as_str(), output_pattern)
    } else if let Some(s_order) = sort_flag {
        let output_pattern = match pos_args.last() {
            Some(o) => o.clone(),
            None => {
                eprintln!("error: [output-format] output formatter must be set");
                std::process::exit(1);
            }
        };
        RunMode::Sort(s_order.as_str(), output_pattern)
    } else if let Some(m_path) = map_flag {
        RunMode::Map(m_path.as_str())
    } else if pos_args.len() >= 2 {
        let source = &pos_args[pos_args.len() - 2];
        let output = pos_args[pos_args.len() - 1].clone();
        RunMode::Regex(source.as_str(), output)
    } else {
        eprintln!("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.");
        eprintln!(
            "usage: run '{} --help' for more information.",
            std::env::args().next().unwrap_or_else(|| "executable".to_string())
        );
        std::process::exit(1);
    };

    let mut map: IndexMap<String, String> = IndexMap::new();

    match run_mode {
        RunMode::Map(m_path) => {
            let content = match fs::read_to_string(m_path) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            };
            let parsed_map: IndexMap<String, String> = match serde_json::from_str(&content) {
                Ok(m) => m,
                Err(e) => {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            };
            map = parsed_map;
        }
        RunMode::Sort(order, output_pattern) => {
            let mut entries = Vec::new();
            if let Ok(read_dir) = fs::read_dir(".") {
                for entry in read_dir.flatten() {
                    let name = entry.file_name().to_string_lossy().to_string();
                    if name != "." && name != ".." {
                        entries.push(name);
                    }
                }
            }
            if order == "desc" {
                entries.sort_by(|a, b| natural_cmp(b, a));
            } else {
                entries.sort_by(|a, b| natural_cmp(a, b));
            }

            for (idx, input_path) in entries.into_iter().enumerate() {
                let enumerator = idx + 1;
                let formatted = match format_output(&output_pattern, None, Some(enumerator), &input_path) {
                    Ok(f) => f,
                    Err(e) => {
                        eprintln!("{}", e);
                        std::process::exit(1);
                    }
                };
                let out_with_ext = append_extension(&formatted, &input_path, no_extension);
                let final_output = resolve_conflict(&out_with_ext, overwrite);
                map.insert(final_output, input_path);
            }
        }
        RunMode::Regex(pattern_str, output_pattern) => {
            let re = match Regex::new(pattern_str) {
                Ok(r) => r,
                Err(e) => {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            };

            let (min_depth, max_depth) = if let Some(m) = max_depth_opt {
                (1, m)
            } else if let Some(d) = depth_opt {
                (d, d)
            } else {
                let inferred = pattern_str.split('/').count();
                (inferred, inferred)
            };

            let mut matched_entries = Vec::new();

            for entry in walkdir::WalkDir::new(".")
                .min_depth(min_depth)
                .max_depth(max_depth)
                .into_iter()
                .filter_map(Result::ok)
            {
                let path = entry.path();
                let rel_path = path.strip_prefix("./").unwrap_or(path);
                let rel_str = rel_path.to_string_lossy().to_string();
                if re.is_match(&rel_str) {
                    matched_entries.push(rel_str);
                }
            }

            matched_entries.sort();

            for input_path in matched_entries {
                if let Some(caps) = re.captures(&input_path) {
                    let formatted = match format_output(&output_pattern, Some(&caps), None, &input_path) {
                        Ok(f) => f,
                        Err(e) => {
                            eprintln!("{}", e);
                            std::process::exit(1);
                        }
                    };
                    let out_with_ext = append_extension(&formatted, &input_path, no_extension);
                    let final_output = resolve_conflict(&out_with_ext, overwrite);
                    map.insert(final_output, input_path);
                }
            }
        }
    }

    if let Some(g_path) = generate_path {
        let json_str = match serde_json::to_string_pretty(&map) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        };
        if let Err(e) = fs::write(g_path, json_str) {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }

    if !quiet {
        print_table(&map);
    }

    if !test_mode {
        for (output_path, input_path) in &map {
            if make_dir {
                if let Some(parent) = Path::new(output_path).parent() {
                    if !parent.as_os_str().is_empty() {
                        let _ = fs::create_dir_all(parent);
                    }
                }
            }
            if let Err(e) = fs::rename(input_path, output_path) {
                eprintln!("[error] unable to rename '{}': {}", input_path, e);
                std::process::exit(1);
            }
        }
    }
}

fn append_extension(out_str: &str, original_path: &str, no_extension: bool) -> String {
    if no_extension {
        return out_str.to_string();
    }
    let p = Path::new(original_path);
    if let Some(ext) = p.extension().and_then(|s| s.to_str()) {
        if !ext.is_empty() {
            return format!("{}.{}", out_str, ext);
        }
    }
    out_str.to_string()
}

fn resolve_conflict(output_path: &str, overwrite: bool) -> String {
    if overwrite {
        return output_path.to_string();
    }
    let path = Path::new(output_path);
    if !path.exists() {
        return output_path.to_string();
    }

    let parent = path.parent();
    let file_name = path.file_name().and_then(|s| s.to_str()).unwrap_or("");

    let mut new_name = format!("_{}", file_name);
    loop {
        let new_path = match parent {
            Some(p) if !p.as_os_str().is_empty() => p.join(&new_name),
            _ => PathBuf::from(&new_name),
        };
        if !new_path.exists() {
            return new_path.to_string_lossy().to_string();
        }
        new_name = format!("_{}", new_name);
    }
}

fn print_table(map: &IndexMap<String, String>) {
    if map.is_empty() {
        return;
    }

    let mut col1_width = "Input".len();
    let mut col2_width = "Output".len();

    for (output, input) in map {
        col1_width = col1_width.max(input.len());
        col2_width = col2_width.max(output.len());
    }

    let border = format!("+{}+{}+", "-".repeat(col1_width + 2), "-".repeat(col2_width + 2));
    println!("{}", border);
    println!("| {:<1$} | {:<2$} |", "Input", col1_width, "Output", col2_width);
    println!("{}", border);
    for (output, input) in map {
        println!("| {:<1$} | {:<2$} |", input, col1_width, output, col2_width);
    }
    println!("{}", border);
}

fn format_output(
    pattern: &str,
    caps: Option<&regex::Captures>,
    sort_index: Option<usize>,
    input_path: &str,
) -> Result<String, String> {
    let mut result = String::new();
    let mut chars = pattern.chars().peekable();
    let mut auto_inc = 1;

    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next_c) = chars.peek() {
                if next_c == '{' || next_c == '}' || next_c == '\\' {
                    result.push(next_c);
                    chars.next();
                    continue;
                }
            }
            result.push('\\');
        } else if c == '{' {
            let mut inner = String::new();
            let mut closed = false;
            while let Some(nc) = chars.next() {
                if nc == '}' {
                    closed = true;
                    break;
                }
                inner.push(nc);
            }
            if !closed {
                return Err("error: [output-format] all opened placeholders must be closed by '}'".to_string());
            }

            let (group_str, padding_str) = match inner.split_once(':') {
                Some((g, p)) => (g, Some(p)),
                None => (inner.as_str(), None),
            };

            let padding = if let Some(p_str) = padding_str {
                if p_str.is_empty() {
                    0
                } else {
                    p_str.parse::<usize>().map_err(|_| {
                        format!("error: [output-format] unable to parse padding of '{}'", p_str)
                    })?
                }
            } else {
                0
            };

            let val_str = if group_str.is_empty() {
                let g = auto_inc;
                auto_inc += 1;
                get_group_val(g, caps, sort_index, input_path)
            } else if let Ok(idx) = group_str.parse::<usize>() {
                get_group_val(idx, caps, sort_index, input_path)
            } else {
                get_named_group_val(group_str, caps)
            };

            if padding > 0 {
                if let Ok(num) = val_str.parse::<u64>() {
                    result.push_str(&format!("{:01$}", num, padding));
                } else {
                    result.push_str(&val_str);
                }
            } else {
                result.push_str(&val_str);
            }
        } else if c == '}' {
            return Err("error: [output-format] an unopened placeholder could not be closed by '}'".to_string());
        } else {
            result.push(c);
        }
    }

    Ok(result)
}

fn get_group_val(
    idx: usize,
    caps: Option<&regex::Captures>,
    sort_index: Option<usize>,
    input_path: &str,
) -> String {
    if let Some(caps) = caps {
        caps.get(idx).map(|m| m.as_str().to_string()).unwrap_or_default()
    } else if let Some(s_idx) = sort_index {
        if idx == 0 {
            input_path.to_string()
        } else if idx == 1 {
            s_idx.to_string()
        } else {
            String::new()
        }
    } else {
        String::new()
    }
}

fn get_named_group_val(name: &str, caps: Option<&regex::Captures>) -> String {
    if let Some(caps) = caps {
        caps.name(name).map(|m| m.as_str().to_string()).unwrap_or_default()
    } else {
        String::new()
    }
}

pub fn natural_cmp(a: &str, b: &str) -> Ordering {
    let mut a_bytes = a.bytes().peekable();
    let mut b_bytes = b.bytes().peekable();

    loop {
        match (a_bytes.peek(), b_bytes.peek()) {
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
            (Some(&ca), Some(&cb)) => {
                if ca.is_ascii_digit() && cb.is_ascii_digit() {
                    let mut a_digits = Vec::new();
                    while let Some(&c) = a_bytes.peek() {
                        if c.is_ascii_digit() {
                            a_digits.push(c);
                            a_bytes.next();
                        } else {
                            break;
                        }
                    }
                    let mut b_digits = Vec::new();
                    while let Some(&c) = b_bytes.peek() {
                        if c.is_ascii_digit() {
                            b_digits.push(c);
                            b_bytes.next();
                        } else {
                            break;
                        }
                    }

                    let a_zeros = a_digits.iter().take_while(|&&c| c == b'0').count();
                    let b_zeros = b_digits.iter().take_while(|&&c| c == b'0').count();

                    if a_digits.len() == a_zeros && b_digits.len() == b_zeros {
                        if a_zeros != b_zeros {
                            return b_zeros.cmp(&a_zeros);
                        }
                    } else if a_zeros > 0 || b_zeros > 0 {
                        if a_zeros != b_zeros {
                            return b_zeros.cmp(&a_zeros);
                        }
                    }

                    let a_trim = &a_digits[a_zeros..];
                    let b_trim = &b_digits[b_zeros..];

                    if a_trim.len() != b_trim.len() {
                        return a_trim.len().cmp(&b_trim.len());
                    }
                    if a_trim != b_trim {
                        return a_trim.cmp(b_trim);
                    }
                } else {
                    if ca != cb {
                        return ca.cmp(&cb);
                    }
                    a_bytes.next();
                    b_bytes.next();
                }
            }
        }
    }
}
