    } else if let Some(m_path) = map_flag {
        RunMode::Map(m_path.as_str())
    } else if pos_args.len() >= 2 {
        let source = &pos_args[pos_args.len() - 2];
        let output = pos_args[pos_args.len() - 1].clone();
        RunMode::Regex(source.as_str(), output)
    } else {
        eprintln!("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.");
        eprintln!(
            "usage: run '{} --help' for more information.",
            std::env::args().next().unwrap_or_else(|| "executable".to_string())
