                };
                let out_with_ext = append_extension(&formatted, &input_path, no_extension);
                let final_output = resolve_conflict(&out_with_ext, overwrite);
                map.insert(final_output, input_path);
            }
        }
        RunMode::Regex(pattern_str, output_pattern) => {
            let re = match Regex::new(pattern_str) {
                Ok(r) => r,
                Err(e) => {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            };

            let (min_depth, max_depth) = if let Some(m) = max_depth_opt {
                (1, m)
            } else if let Some(d) = depth_opt {
                (d, d)
            } else {
                let inferred = pattern_str.split('/').count();
                (inferred, inferred)
            };

            let mut matched_entries = Vec::new();

            for entry in walkdir::WalkDir::new(".")
                .min_depth(min_depth)
                .max_depth(max_depth)
                .into_iter()
                .filter_map(Result::ok)
            {
                let path = entry.path();
                let rel_path = path.strip_prefix("./").unwrap_or(path);
                let rel_str = rel_path.to_string_lossy().to_string();
                if re.is_match(&rel_str) {
                    matched_entries.push(rel_str);
                }
            }

            matched_entries.sort();

            for input_path in matched_entries {
                if let Some(caps) = re.captures(&input_path) {
                    let formatted = match format_output(&output_pattern, Some(&caps), None, &input_path) {
                        Ok(f) => f,
                        Err(e) => {
                            eprintln!("{}", e);
                            std::process::exit(1);
                        }
                    };
                    let out_with_ext = append_extension(&formatted, &input_path, no_extension);
                    let final_output = resolve_conflict(&out_with_ext, overwrite);
                    map.insert(final_output, input_path);
                }
            }
        }
    }

    if let Some(g_path) = generate_path {
        let json_str = match serde_json::to_string_pretty(&map) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        };
        if let Err(e) = fs::write(g_path, json_str) {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }

    if !quiet {
        print_table(&map);
    }

    if !test_mode {
        for (output_path, input_path) in &map {
            if make_dir {
                if let Some(parent) = Path::new(output_path).parent() {
                    if !parent.as_os_str().is_empty() {
                        let _ = fs::create_dir_all(parent);
                    }
                }
            }
            if let Err(e) = fs::rename(input_path, output_path) {
                eprintln!("[error] unable to rename '{}': {}", input_path, e);
                std::process::exit(1);
            }
        }
    }
}

fn append_extension(out_str: &str, original_path: &str, no_extension: bool) -> String {
    if no_extension {
        return out_str.to_string();
    }
    let p = Path::new(original_path);
    if let Some(ext) = p.extension().and_then(|s| s.to_str()) {
        if !ext.is_empty() {
            return format!("{}.{}", out_str, ext);
        }
    }
    out_str.to_string()
}

fn resolve_conflict(output_path: &str, overwrite: bool) -> String {
    if overwrite {
        return output_path.to_string();
    }
    let path = Path::new(output_path);
    if !path.exists() {
        return output_path.to_string();
    }

    let parent = path.parent();
    let file_name = path.file_name().and_then(|s| s.to_str()).unwrap_or("");

    let mut new_name = format!("_{}", file_name);
    loop {
        let new_path = match parent {
            Some(p) if !p.as_os_str().is_empty() => p.join(&new_name),
            _ => PathBuf::from(&new_name),
        };
        if !new_path.exists() {
            return new_path.to_string_lossy().to_string();
        }
        new_name = format!("_{}", new_name);
    }
}

fn print_table(map: &IndexMap<String, String>) {
    if map.is_empty() {
        return;
    }

    let mut col1_width = "Input".len();
    let mut col2_width = "Output".len();

    for (output, input) in map {
        col1_width = col1_width.max(input.len());
        col2_width = col2_width.max(output.len());
    }

    let border = format!("+{}+{}+", "-".repeat(col1_width + 2), "-".repeat(col2_width + 2));
    println!("{}", border);
    println!("| {:<w1$} | {:<w2$} |", "Input", "Output", w1 = col1_width, w2 = col2_width);
    println!("{}", border);
    for (output, input) in map {
        println!("| {:<w1$} | {:<w2$} |", input, output, w1 = col1_width, w2 = col2_width);
    }
    println!("{}", border);
}

fn format_output(
    pattern: &str,
    caps: Option<&regex::Captures>,
    sort_index: Option<usize>,
    input_path: &str,
) -> Result<String, String> {
    let mut result = String::new();
    let mut chars = pattern.chars().peekable();
    let mut auto_inc = 1;

    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next_c) = chars.peek() {
                if next_c == '{' || next_c == '}' || next_c == '\\' {
                    result.push(next_c);
                    chars.next();
                    continue;
                }
            }
            result.push('\\');
        } else if c == '{' {
            let mut inner = String::new();
            let mut closed = false;
            while let Some(nc) = chars.next() {
                if nc == '}' {
                    closed = true;
                    break;
                }
                inner.push(nc);
            }
            if !closed {
                return Err("error: [output-format] all opened placeholders must be closed by '}'".to_string());
            }

            let (group_str, padding_str) = match inner.split_once(':') {
                Some((g, p)) => (g, Some(p)),
                None => (inner.as_str(), None),
            };

            let padding = if let Some(p_str) = padding_str {
                if p_str.is_empty() {
                    0
                } else {
                    p_str.parse::<usize>().map_err(|_| {
                        format!("error: [output-format] unable to parse padding of '{}'", p_str)
                    })?
                }
            } else {
                0
            };

            let val_str = if group_str.is_empty() {
                let g = auto_inc;
                auto_inc += 1;
                get_group_val(g, caps, sort_index, input_path)
            } else if let Ok(idx) = group_str.parse::<usize>() {
                get_group_val(idx, caps, sort_index, input_path)
            } else {
                get_named_group_val(group_str, caps)
            };

            if padding > 0 {
                if let Ok(num) = val_str.parse::<u64>() {
                    result.push_str(&format!("{:01$}", num, padding));
                } else {
                    result.push_str(&val_str);
                }
            } else {
                result.push_str(&val_str);
            }
        } else if c == '}' {
            return Err("error: [output-format] an unopened placeholder could not be closed by '}'".to_string());
        } else {
            result.push(c);
        }
    }

    Ok(result)
}

fn get_group_val(
    idx: usize,
    caps: Option<&regex::Captures>,
    sort_index: Option<usize>,
    input_path: &str,
) -> String {
    if let Some(caps) = caps {
        caps.get(idx).map(|m| m.as_str().to_string()).unwrap_or_default()
    } else if let Some(s_idx) = sort_index {
        if idx == 0 {
            input_path.to_string()
        } else if idx == 1 {
            s_idx.to_string()
        } else {
            String::new()
        }
    } else {
        String::new()
    }
}

fn get_named_group_val(name: &str, caps: Option<&regex::Captures>) -> String {
    if let Some(caps) = caps {
        caps.name(name).map(|m| m.as_str().to_string()).unwrap_or_default()
    } else {
        String::new()
    }
}

pub fn natural_cmp(a: &str, b: &str) -> Ordering {
    let mut a_bytes = a.bytes().peekable();
    let mut b_bytes = b.bytes().peekable();

    loop {
        match (a_bytes.peek(), b_bytes.peek()) {
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
            (Some(&ca), Some(&cb)) => {
                if ca.is_ascii_digit() && cb.is_ascii_digit() {
                    let mut a_digits = Vec::new();
                    while let Some(&c) = a_bytes.peek() {
                        if c.is_ascii_digit() {
                            a_digits.push(c);
                            a_bytes.next();
                        } else {
                            break;
                        }
                    }
                    let mut b_digits = Vec::new();
                    while let Some(&c) = b_bytes.peek() {
                        if c.is_ascii_digit() {
                            b_digits.push(c);
                            b_bytes.next();
                        } else {
                            break;
                        }
                    }

                    let a_zeros = a_digits.iter().take_while(|&&c| c == b'0').count();
                    let b_zeros = b_digits.iter().take_while(|&&c| c == b'0').count();

                    if a_digits.len() == a_zeros && b_digits.len() == b_zeros {
                        if a_zeros != b_zeros {
                            return b_zeros.cmp(&a_zeros);
                        }
                    } else if a_zeros > 0 || b_zeros > 0 {
                        if a_zeros != b_zeros {
                            return b_zeros.cmp(&a_zeros);
                        }
                    }

                    let a_trim = &a_digits[a_zeros..];
                    let b_trim = &b_digits[b_zeros..];

                    if a_trim.len() != b_trim.len() {
                        return a_trim.len().cmp(&b_trim.len());
                    }
                    if a_trim != b_trim {
                        return a_trim.cmp(b_trim);
                    }
                } else {
                    if ca != cb {
                        return ca.cmp(&cb);
                    }
                    a_bytes.next();
                    b_bytes.next();
                }
            }
        }
    }
}
